contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 depositAmount) public payable {
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);
        c.deposit{value: depositAmount}();
        c.refund();
        bool reverted;
        try c.withdraw(1) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}
